    return density_map

def read_stl(filepath):
    triangles = []
    with open(filepath, 'rb') as f:
        header = f.read(80)
        count_bytes = f.read(4)
        if len(count_bytes) < 4:
            return []
        count = struct.unpack('<I', count_bytes)[0]
        for _ in range(count):
            record = f.read(50)
            if len(record) < 50:
                break
            data = struct.unpack('<3f3f3f3fH', record)
            normal = data[0:3]
            v1 = data[3:6]
            v2 = data[6:9]
            v3 = data[9:12]
            attr = data[12]
            triangles.append({'v1': v1, 'v2': v2, 'v3': v3, 'attr': attr})
    return triangles

def get_connected_components(triangles):
    vertex_map = {}
    for idx, tri in enumerate(triangles):
        for v in [tri['v1'], tri['v2'], tri['v3']]:
            if v not in vertex_map:
                vertex_map[v] = []
            vertex_map[v].append(idx)
    visited = set()
    components = []
    for i in range(len(triangles)):
        if i in visited:
            continue
        component = []
        stack = [i]
        visited.add(i)
        while stack:
            curr_idx = stack.pop()
            component.append(curr_idx)
            tri = triangles[curr_idx]
            for v in [tri['v1'], tri['v2'], tri['v3']]:
                for n_idx in vertex_map[v]:
                    if n_idx not in visited:
                        visited.add(n_idx)
                        stack.append(n_idx)
        components.append(component)
    return components

def signed_volume_of_triangle(p1, p2, p3):
    return (1.0/6.0) * (p1[0]*p2[1]*p3[2] - p1[0]*p3[1]*p2[2] - p2[0]*p1[1]*p3[2] + p2[0]*p3[1]*p1[2] + p3[0]*p1[1]*p2[2] - p3[0]*p2[1]*p1[2])

def main():
